package store

// Original JLPT N5 practice papers 02-05 (papers 06+ are JSON files) with furigana markup {kanji|reading}.
// Correct choice first; shuffled by the server per attempt.
func simulationN5AdditionalContent(paperNo int) []simulationItem {
	switch paperNo {
	case 2:
		return simulationN5Content2()
	case 3:
		return simulationN5Content3()
	case 4:
		return simulationN5Content4()
	case 5:
		return simulationN5Content5()
	default:
		// Papers 06 and later live in simulation_data/*.json (see simulation_json.go).
		return simulationJSONContent("N5", paperNo)
	}
}

